var BuildingAlertsWidget = (function() {
  var relationCache = {};

  function esc(value) {
    return String(value == null ? '' : value)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/\"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function pad(value) {
    return value < 10 ? '0' + value : String(value);
  }

  function formatTime(timestamp) {
    if (timestamp === undefined || timestamp === null || timestamp === 0) {
      return '';
    }
    var date = new Date(Number(timestamp));
    if (isNaN(date.getTime())) {
      return '';
    }
    return pad(date.getDate()) + '/' + pad(date.getMonth() + 1) + '/' +
      date.getFullYear() + ' ' + pad(date.getHours()) + ':' +
      pad(date.getMinutes()) + ':' + pad(date.getSeconds());
  }

  function entityId(value, fallbackType) {
    if (!value) {
      return { entityType: fallbackType || 'DEVICE', id: '' };
    }
    if (typeof value === 'string') {
      return { entityType: fallbackType || 'DEVICE', id: value };
    }
    var rawId = value.id;
    if (rawId && typeof rawId === 'object') {
      rawId = rawId.id;
    }
    return {
      entityType: value.entityType || fallbackType || 'DEVICE',
      id: rawId == null ? '' : String(rawId)
    };
  }

  function alarmOriginator(alarm) {
    var originator = alarm && (alarm.originator || alarm.originatorId || alarm.entityId);
    var ref = entityId(originator, 'DEVICE');
    var name = alarm && (alarm.originatorName || alarm.entityName || alarm.deviceName);
    if (!name && originator && typeof originator === 'object') {
      name = originator.name;
    }
    return { entityType: ref.entityType, id: ref.id, name: name || 'Unknown device' };
  }

  function alarmStatus(alarm) {
    if (alarm && alarm.status) {
      return String(alarm.status).toUpperCase();
    }
    if (alarm && alarm.cleared) {
      return alarm.acknowledged ? 'CLEARED_ACK' : 'CLEARED_UNACK';
    }
    return alarm && alarm.acknowledged ? 'ACTIVE_ACK' : 'ACTIVE_UNACK';
  }

  function displayStatus(status) {
    switch (status) {
      case 'ACTIVE_UNACK': return 'Active Unacknowledged';
      case 'ACTIVE_ACK': return 'Active Acknowledged';
      case 'CLEARED_UNACK': return 'Cleared Unacknowledged';
      case 'CLEARED_ACK': return 'Cleared Acknowledged';
      default: return status || 'Unknown';
    }
  }

  function assigneeName(value) {
    if (!value) {
      return 'Unassigned';
    }
    if (typeof value === 'string') {
      return value;
    }
    return value.email || value.name || value.id || 'Assigned';
  }

  function detailsText(value) {
    if (value === undefined || value === null || value === '') {
      return 'No alarm details supplied.';
    }
    if (typeof value === 'string') {
      return value;
    }
    try {
      return JSON.stringify(value, null, 2);
    } catch (error) {
      return String(value);
    }
  }

  function relationTarget(relation) {
    if (!relation) {
      return null;
    }
    var from = relation.from || relation.fromId;
    var ref = entityId(from, 'ASSET');
    if (!ref.id) {
      return null;
    }
    return {
      entityType: ref.entityType,
      id: ref.id,
      name: relation.fromName || relation.entityName || (from && from.name) || '',
      relationType: relation.relationType || relation.type || ''
    };
  }

  function liveRow(alarm) {
    var originator = alarmOriginator(alarm);
    var status = alarmStatus(alarm);
    var alarmId = entityId(alarm && alarm.id, 'ALARM').id;
    var cache = relationCache[originator.id];
    return {
      id: alarmId || [originator.id, alarm && alarm.type, alarm && alarm.createdTime].join('|'),
      alarm: alarm,
      originatorId: originator.id,
      originatorType: originator.entityType,
      name: originator.name,
      type: alarm && alarm.type ? alarm.type : 'Alarm',
      building: cache && cache.name ? cache.name : (cache && cache.loading ? 'Resolving building…' : 'No building TO relation'),
      buildingId: cache && cache.id ? cache.id : '',
      relationType: cache && cache.relationType ? cache.relationType : 'Contains',
      severity: alarm && alarm.severity ? String(alarm.severity).toUpperCase() : 'INDETERMINATE',
      assignee: assigneeName(alarm && alarm.assignee),
      statusKey: status,
      status: displayStatus(status),
      created: alarm && (alarm.createdTime || alarm.startTs),
      ackTs: alarm && alarm.ackTs,
      clearTs: alarm && alarm.clearTs,
      description: detailsText(alarm && alarm.details)
    };
  }

  function alarmValue(value) {
    if (Array.isArray(value)) {
      return value.length > 1 ? value[1] : value[0];
    }
    if (value && typeof value === 'object') {
      if (value.value !== undefined) return value.value;
      if (value.v !== undefined) return value.v;
    }
    return value;
  }

  function normalKey(value) {
    return String(value == null ? '' : value).toLowerCase().replace(/[^a-z0-9]/g, '');
  }

  function seriesAlarms(data) {
    var byKey = {};
    var maxLength = 0;
    (Array.isArray(data) ? data : []).forEach(function(series) {
      if (!series || !series.dataKey) return;
      var key = normalKey(series.dataKey.name || series.dataKey.label);
      if (!key) return;
      var values = Array.isArray(series.data) ? series.data.map(alarmValue) : [];
      byKey[key] = values;
      if (values.length > maxLength) maxLength = values.length;
    });
    if (!maxLength) return [];
    var alarms = [];
    for (var i = 0; i < maxLength; i++) {
      var alarm = {
        id: byKey.id && byKey.id[i],
        createdTime: byKey.createdtime && byKey.createdtime[i],
        originator: byKey.originator && byKey.originator[i],
        originatorName: byKey.originatorname && byKey.originatorname[i],
        type: byKey.type && byKey.type[i],
        severity: byKey.severity && byKey.severity[i],
        assignee: byKey.assignee && byKey.assignee[i],
        status: byKey.status && byKey.status[i],
        ackTs: byKey.ackts && byKey.ackts[i],
        clearTs: byKey.clearts && byKey.clearts[i]
      };
      if (alarm.id || alarm.createdTime || alarm.originator || alarm.type) alarms.push(alarm);
    }
    return alarms;
  }

  function unwrapAlarm(item) {
    if (!item || typeof item !== 'object') return null;
    var alarm = item.alarm && typeof item.alarm === 'object' ? item.alarm : item;
    if (!alarm.id) return null;
    if (!alarm.originator && item.entity && item.entity.id) alarm.originator = item.entity;
    if (!alarm.originatorName && item.entity && item.entity.name) alarm.originatorName = item.entity.name;
    return alarm;
  }

  function init(root, options) {
    options = options || {};
    var ctx = options.ctx || null;
    var state = {
      rows: [],
      status: 'ACTIVE',
      type: 'ALL',
      building: 'ALL',
      severity: 'ALL',
      search: '',
      page: 1,
      pageSize: 50,
      sortKey: 'created',
      sortDirection: 'desc',
      selected: null,
      tab: 'details',
      loading: true,
      serverPage: 0,
      serverPageCount: 1,
      serverTotal: 0
    };
    var alarmService = null;
    var relationService = null;
    var entityService = null;
    var dataListener = null;
    var serviceReady = false;
    var queryInFlight = false;
    var querySequence = 0;
    var pollHandle = null;
    var queryRowsReady = false;
    var relationQueueToken = 0;

    var rowsEl = root.querySelector('[data-rows]');
    var emptyEl = root.querySelector('[data-empty]');
    var loadingEl = root.querySelector('[data-loading]');
    var rangeEl = root.querySelector('[data-range]');
    var pageSizeEl = root.querySelector('[data-page-size]');
    var modal = root.querySelector('[data-modal]');
    var modalBody = root.querySelector('[data-modal-body]');
    var modalTitle = root.querySelector('[data-modal-title]');
    var toast = root.querySelector('[data-toast]');
    var searchBox = root.querySelector('[data-search-box]');
    var searchInput = root.querySelector('[data-search-input]');
    var filterPanel = root.querySelector('[data-filter-panel]');
    var refreshNote = root.querySelector('[data-refresh-note]');
    var typeFilter = root.querySelector('[data-filter="type"]');
    var buildingFilter = root.querySelector('[data-filter="building"]');
    var statusFilter = root.querySelector('[data-filter="status"]');
    var severityFilter = root.querySelector('[data-filter="severity"]');

    function showToast(message) {
      if (!toast) return;
      toast.textContent = message;
      toast.hidden = false;
      window.clearTimeout(showToast.timer);
      showToast.timer = window.setTimeout(function() { toast.hidden = true; }, 2800);
    }
    function applyCounterFilter(detail) {
      detail = detail || {};
      if (detail.source !== 'hvac_alarms_counter') return;
      state.status = String(detail.status || 'ALL').toUpperCase();
      state.severity = String(detail.severity || 'ALL').toUpperCase();
      state.type = 'ALL';
      state.building = 'ALL';
      state.search = '';
      state.page = 1;
      state.serverPage = 0;
      state.serverPageCount = 1;
      state.serverTotal = 0;
      queryRowsReady = false;
      if (statusFilter) statusFilter.value = state.status;
      if (severityFilter) severityFilter.value = state.severity;
      if (typeFilter) typeFilter.value = 'ALL';
      if (buildingFilter) buildingFilter.value = 'ALL';
      if (searchInput) searchInput.value = '';
      state.loading = true;
      queryLiveAlarms();
      render();
    }

    function counterFilterHandler(event) {
      applyCounterFilter(event && event.detail);
    }

    function relationValues() {
      var types = {};
      var buildings = {};
      state.rows.forEach(function(row) {
        if (row.type) types[row.type] = true;
        if (row.building && row.building !== 'Resolving building…') buildings[row.building] = true;
      });
      return { types: Object.keys(types).sort(), buildings: Object.keys(buildings).sort() };
    }

    function syncSelect(select, firstLabel, values, selected) {
      if (!select) return;
      var html = '<option value="ALL">' + esc(firstLabel) + '</option>';
      values.forEach(function(value) { html += '<option value="' + esc(value) + '">' + esc(value) + '</option>'; });
      select.innerHTML = html;
      select.value = values.indexOf(selected) >= 0 ? selected : 'ALL';
    }

    function filteredRows() {
      var rows = state.rows.filter(function(row) {
        var statusOk = state.status === 'ALL' ||
          (state.status === 'ACTIVE' && (row.statusKey === 'ACTIVE_UNACK' || row.statusKey === 'ACTIVE_ACK')) ||
          (state.status === 'UNACK' && (row.statusKey === 'ACTIVE_UNACK' || row.statusKey === 'CLEARED_UNACK')) ||
          (state.status === 'ACK' && (row.statusKey === 'ACTIVE_ACK' || row.statusKey === 'CLEARED_ACK')) ||
          row.statusKey === state.status;
        var textOk = !state.search || [row.name, row.type, row.building, row.assignee, row.status]
          .join(' ').toLowerCase().indexOf(state.search.toLowerCase()) >= 0;
        return statusOk && (state.type === 'ALL' || row.type === state.type) &&
          (state.building === 'ALL' || row.building === state.building) &&
          (state.severity === 'ALL' || row.severity === state.severity) && textOk;
      });
      rows.sort(function(a, b) {
        var comparison;
        if (state.sortKey === 'building') {
          comparison = String(a.building || '').localeCompare(String(b.building || ''), undefined, { sensitivity: 'base' });
          if (!comparison) comparison = String(a.name || '').localeCompare(String(b.name || ''), undefined, { sensitivity: 'base' });
        } else {
          comparison = Number(a.created || 0) - Number(b.created || 0);
        }
        if (!comparison) comparison = Number(a.created || 0) - Number(b.created || 0);
        return state.sortDirection === 'asc' ? comparison : -comparison;
      });
      return rows;
    }

    function rowHtml(row) {
      var severityClass = 'ba-' + String(row.severity || 'indeterminate').toLowerCase();
      var statusClass = 'ba-status-' + String(row.statusKey || '').toLowerCase();
      return '<tr data-row-id="' + esc(row.id) + '">' +
        '<td class="ba-check-col"><input type="checkbox" aria-label="Select ' + esc(row.name) + '"></td>' +
        '<td>' + esc(formatTime(row.created)) + '</td>' +
        '<td><a class="ba-name-link" data-action="details" data-id="' + esc(row.id) + '">' + esc(row.name) + '</a></td>' +
        '<td>' + esc(row.type) + '</td>' +
        '<td><div class="ba-building-cell"><a class="ba-building-link" data-action="details" data-id="' + esc(row.id) + '">' + esc(row.building) + '</a><span class="ba-relation-pill">TO</span></div></td>' +
        '<td><span class="ba-severity ' + severityClass + '">' + esc(row.severity) + '</span></td>' +
        '<td><span class="ba-assignee"><span class="ba-avatar">●</span>' + esc(row.assignee) + '</span></td>' +
        '<td><span class="ba-status ' + statusClass + '">' + esc(row.status) + '</span></td>' +
        '<td class="ba-details-col"><button class="ba-details-btn" type="button" data-action="details" data-id="' + esc(row.id) + '" aria-label="Open details for ' + esc(row.name) + '">•••</button></td>' +
        '</tr>';
    }

    function render() {
      if (!rowsEl) return;
      var values = relationValues();
      syncSelect(typeFilter, 'All alert types', values.types, state.type);
      syncSelect(buildingFilter, 'All buildings', values.buildings, state.building);
      var source = filteredRows();
      var maxPage = Math.max(1, state.serverPageCount || Math.ceil(source.length / state.pageSize));
      if (state.page > maxPage) state.page = maxPage;
      var start = 0;
      var visible = source.slice(0, state.pageSize);
      rowsEl.innerHTML = visible.map(rowHtml).join('');
      if (loadingEl) loadingEl.hidden = !state.loading;
      if (emptyEl) emptyEl.hidden = state.loading || visible.length > 0;
      if (rangeEl) {
        if (state.loading && !source.length) rangeEl.textContent = 'Loading…';
        else if (visible.length && state.serverTotal) {
          var serverStart = state.serverPage * state.pageSize + 1;
          rangeEl.textContent = serverStart + ' – ' + (serverStart + visible.length - 1) + ' of ' + state.serverTotal;
        } else rangeEl.textContent = source.length ? '1 – ' + Math.min(state.pageSize, source.length) + ' of ' + source.length : '0 of 0';
      }
      var prev = root.querySelector('[data-action="prev"]');
      var next = root.querySelector('[data-action="next"]');
      if (prev) prev.disabled = state.page <= 1;
      if (next) next.disabled = state.page >= maxPage;
      var filterBtn = root.querySelector('[data-action="filter"]');
      if (filterBtn) filterBtn.innerHTML = '<span class="ba-icon">≡</span> Filter: ' + (state.status === 'ACTIVE' ? 'Active' : state.status === 'ALL' ? 'All' : state.status);
      var buildingSort = root.querySelector('[data-action="sort"][data-sort-key="building"]');
      if (buildingSort) {
        var sortIndicator = buildingSort.querySelector('.ba-sort');
        if (sortIndicator) sortIndicator.textContent = state.sortKey === 'building' ? (state.sortDirection === 'asc' ? '↑' : '↓') : '↕';
        buildingSort.setAttribute('aria-sort', state.sortKey === 'building' ? state.sortDirection : 'none');
      }
      if (modal && !modal.hidden && state.selected) renderModal();
    }

    function currentRow() {
      return state.rows.find(function(row) { return row.id === state.selected; }) || null;
    }

    function detailsHtml(row) {
      return '<div class="ba-detail-grid">' +
        '<div><span class="ba-detail-label">Name</span><span class="ba-detail-value">' + esc(row.name) + '</span></div>' +
        '<div><span class="ba-detail-label">Alert type</span><span class="ba-detail-value">' + esc(row.type) + '</span></div>' +
        '<div><span class="ba-detail-label">Building (TO relationship)</span><span class="ba-detail-value">' + esc(row.building) + '</span></div>' +
        '<div><span class="ba-detail-label">Relation type</span><span class="ba-detail-value">' + esc(row.relationType || 'Contains') + '</span></div>' +
        '<div><span class="ba-detail-label">Severity</span><span class="ba-detail-value"><span class="ba-severity ba-' + esc(String(row.severity).toLowerCase()) + '">' + esc(row.severity) + '</span></span></div>' +
        '<div><span class="ba-detail-label">Status</span><span class="ba-detail-value">' + esc(row.status) + '</span></div>' +
        '<div><span class="ba-detail-label">Created time</span><span class="ba-detail-value">' + esc(formatTime(row.created)) + '</span></div>' +
        '<div><span class="ba-detail-label">Assignee</span><span class="ba-detail-value">' + esc(row.assignee) + '</span></div>' +
        '</div><div style="margin-top:24px"><span class="ba-detail-label">Alarm details</span><pre class="ba-detail-value" style="white-space:pre-wrap;font:inherit;margin:0">' + esc(row.description) + '</pre></div>';
    }

    function activityHtml(row) {
      var html = '<div class="ba-activity"><div class="ba-activity-item"><strong>Alert created</strong><div class="ba-activity-time">' + esc(formatTime(row.created)) + '</div></div>';
      if (row.ackTs) html += '<div class="ba-activity-item"><strong>Alert acknowledged</strong><div class="ba-activity-time">' + esc(formatTime(row.ackTs)) + '</div></div>';
      if (row.clearTs) html += '<div class="ba-activity-item"><strong>Alert cleared</strong><div class="ba-activity-time">' + esc(formatTime(row.clearTs)) + '</div></div>';
      if (!row.ackTs && !row.clearTs) html += '<div class="ba-activity-item"><strong>Awaiting operator action</strong><div class="ba-activity-time">No acknowledgement or clear action recorded</div></div>';
      return html + '</div>';
    }

    function relationsHtml(row) {
      return '<div class="ba-relation-flow"><div class="ba-flow-node"><strong>' + esc(row.name) + '</strong><span>' + esc(row.originatorType || 'DEVICE') + ' / alarm originator</span></div><span class="ba-flow-arrow">→</span><div class="ba-flow-node"><strong>' + esc(row.building) + '</strong><span>ASSET / Building (TO)</span></div></div><p style="color:#66757d;margin:0">Resolved from the inbound relationship to this device. The gateway is intentionally not used as the building context.</p>';
    }

    function renderModal() {
      var row = currentRow();
      if (!row || !modalBody || !modalTitle) return;
      modalTitle.textContent = row.type;
      modalBody.innerHTML = state.tab === 'details' ? detailsHtml(row) : state.tab === 'activity' ? activityHtml(row) : relationsHtml(row);
      var ack = modal.querySelector('[data-action="ack-modal"]');
      var clear = modal.querySelector('[data-action="clear-modal"]');
      var active = row.statusKey === 'ACTIVE_UNACK' || row.statusKey === 'ACTIVE_ACK';
      if (ack) { ack.disabled = row.statusKey !== 'ACTIVE_UNACK'; ack.textContent = row.statusKey === 'ACTIVE_UNACK' ? 'Acknowledge' : 'Acknowledged'; }
      if (clear) { clear.disabled = !active; clear.textContent = active ? 'Clear' : 'Cleared'; }
      modal.querySelectorAll('[data-tab]').forEach(function(tab) { tab.classList.toggle('active', tab.getAttribute('data-tab') === state.tab); });
    }

    function openModal(id) {
      state.selected = id;
      state.tab = 'details';
      renderModal();
      if (modal) modal.hidden = false;
    }

    function callAlarmAction(method, message) {
      var row = currentRow();
      var alarmId = row && row.alarm && row.alarm.id ? entityId(row.alarm.id, 'ALARM').id : '';
      if (!row || !alarmId || !alarmService || typeof alarmService[method] !== 'function') {
        showToast('Alarm action is unavailable');
        return;
      }
      var observable;
      try { observable = alarmService[method](alarmId); } catch (error) { showToast('Alarm action failed'); return; }
      if (!observable || typeof observable.subscribe !== 'function') { showToast('Alarm action is unavailable'); return; }
      observable.subscribe(function() {
        var now = Date.now();
        if (method === 'ackAlarm') { row.ackTs = now; row.alarm.ackTs = now; row.alarm.status = 'ACTIVE_ACK'; row.statusKey = 'ACTIVE_ACK'; row.status = 'Active Acknowledged'; }
        if (method === 'clearAlarm') { row.clearTs = now; row.alarm.clearTs = now; row.alarm.status = row.ackTs ? 'CLEARED_ACK' : 'CLEARED_UNACK'; row.statusKey = row.alarm.status; row.status = displayStatus(row.statusKey); }
        render();
        renderModal();
        showToast(message);
      }, function() { showToast('Alarm action failed'); });
    }

    function setRowsFromSubscription() {
      if (!ctx || queryRowsReady) return;
      var alarms = ctx.defaultSubscription && ctx.defaultSubscription.alarms && Array.isArray(ctx.defaultSubscription.alarms.data) ? ctx.defaultSubscription.alarms.data : [];
      if (!alarms.length && Array.isArray(ctx.data)) alarms = seriesAlarms(ctx.data);
      if (!alarms.length) return;
      state.rows = alarms.map(unwrapAlarm).filter(function(alarm) { return !!alarm; }).map(liveRow);
      state.page = 1;
      ensureBuildingsProgressively(state.rows);
      render();
    }

    function resolvedAlarmEntityFilter() {
      var aliasController = ctx && ctx.dashboard && ctx.dashboard.aliasController;
      var source = ctx && ctx.widgetConfig && ctx.widgetConfig.alarmSource;
      var aliasId = source && source.entityAliasId;
      if (aliasController && aliasId) {
        var resolved = aliasController.resolvedAliases && aliasController.resolvedAliases[aliasId];
        var aliasMeta = aliasController.entityAliases && aliasController.entityAliases[aliasId];
        if (resolved && resolved.entityFilter) return resolved.entityFilter;
        if (aliasMeta && aliasMeta.entityFilter) return aliasMeta.entityFilter;
      }
      return null;
    }

    function alarmEntityFilter() {
      // Keep resolveMultiple for the CE 3.9 entity-filter contract. The
      // resolved dashboard alias remains a guarded fallback below.
      return { type: 'entityType', resolveMultiple: true, entityType: 'DEVICE' };
    }

    function serverStatusList() {
      if (state.status === 'ACTIVE') return ['ACTIVE', 'UNACK'];
      if (state.status === 'UNACK') return ['UNACK'];
      if (state.status === 'ACK') return ['ACK'];
      if (state.status === 'CLEARED') return ['CLEARED'];
      return null;
    }

    function queryLiveAlarms() {
      if (!entityService || typeof entityService.findAlarmDataByQuery !== 'function' || queryInFlight) {
        if (!entityService) { state.loading = false; render(); }
        return;
      }
      queryInFlight = true;
      state.loading = true;
      render();
      var sequence = ++querySequence;
      var queryFilter = alarmEntityFilter();
      var fallbackFilter = resolvedAlarmEntityFilter();
      var fallbackTried = false;
      var pageNumber = Math.max(0, state.page - 1);
      var pageLink = {
        pageSize: state.pageSize,
        page: pageNumber,
        textSearch: null,
        sortOrder: { key: { type: 'ALARM_FIELD', key: 'createdTime' }, direction: 'DESC' },
        isDynamic: false,
        startTs: 0,
        endTs: Date.now(),
        statusList: serverStatusList(),
        severityList: state.severity === 'ALL' ? null : [state.severity],
        typeList: state.type === 'ALL' ? null : [state.type],
        searchPropagatedAlarms: true
      };
      var query = {
        entityFilter: queryFilter,
        keyFilters: [],
        pageLink: pageLink,
        entityFields: [],
        latestValues: [],
        alarmFields: []
      };

      function finish(pageData, allowFallback) {
        if (sequence !== querySequence) return;
        var items = pageData && Array.isArray(pageData.data) ? pageData.data : [];
        if (!items.length && allowFallback && fallbackFilter && JSON.stringify(fallbackFilter) !== JSON.stringify(queryFilter)) {
          fallbackTried = true;
          queryFilter = fallbackFilter;
          query.entityFilter = queryFilter;
          try {
            var fallbackObservable = entityService.findAlarmDataByQuery(query);
            if (fallbackObservable && typeof fallbackObservable.subscribe === 'function') {
              fallbackObservable.subscribe(function(result) { finish(result, false); }, function() { finish(null, false); });
              return;
            }
          } catch (error) {}
        }
        var alarms = items.map(unwrapAlarm).filter(function(alarm) { return !!alarm; });
        if (!alarms.length && Array.isArray(ctx && ctx.data)) alarms = seriesAlarms(ctx.data).map(unwrapAlarm).filter(function(alarm) { return !!alarm; });
        queryInFlight = false;
        state.loading = false;
        state.serverPage = pageNumber;
        state.serverTotal = Number(pageData && pageData.totalElements) || alarms.length;
